public static void spawnEntity(World world, LivingEntity owner, ItemStack stack) {
		stack.damage(1, owner, stackUser -> stackUser.sendToolBreakStatus(stackUser.getActiveHand()));
		HornedSpearEntity spear = new HornedSpearEntity(BWEntityTypes.HORNED_SPEAR, owner, world, stack.copy());
		spear.setVelocity(owner, owner.getPitch(), owner.getYaw(), 0, 3, 1);
		if (owner instanceof PlayerEntity player) {
			if (player.isCreative()) {
				spear.pickupType = PersistentProjectileEntity.PickupPermission.CREATIVE_ONLY;
			}
		} else {
			spear.pickupType = PersistentProjectileEntity.PickupPermission.DISALLOWED;
		}
		world.spawnEntity(spear);
		PlayerLookup.tracking(spear).forEach(trackingPlayer -> SyncHornedSpearPacket.send(trackingPlayer, spear));
		world.playSoundFromEntity(null, spear, BWSoundEvents.ITEM_HORNED_SPEAR_USE, SoundCategory.PLAYERS, 1, 1);
		if (owner instanceof PlayerEntity player && !player.isCreative()) {
			stack.decrement(1);
		}
	}

@Override
	public TypedActionResult<ItemStack> use(World world, PlayerEntity user, Hand hand) {
		ItemStack stack = user.getStackInHand(hand);
		if (stack.getDamage() >= stack.getMaxDamage() - 1) {
			return TypedActionResult.fail(stack);
		}
		return ItemUsage.consumeHeldItem(world, user, hand);
	}

@Override
	public void onStoppedUsing(ItemStack stack, World world, LivingEntity user, int remainingUseTicks) {
		int timer = getMaxUseTime(stack) - remainingUseTicks;
		if (timer >= 10) {
			if (!world.isClient) {
				spawnEntity(world, user, stack);
			}
			if (user instanceof PlayerEntity player) {
				player.incrementStat(Stats.USED.getOrCreateStat(this));
			}
		}
	}

@Override
	public int getMaxUseTime(ItemStack stack) {
		return 72000;
	}

@Override
	protected void onEntityHit(EntityHitResult result) {
		Entity owner = getOwner();
		Entity entity = result.getEntity();
		float damage = 7;
		if (entity instanceof LivingEntity livingEntity) {
			damage += EnchantmentHelper.getAttackDamage(spear, livingEntity.getGroup());
		}
		if (owner instanceof HerneEntity) {
			damage *= 3;
		}
		dealtDamage = true;
		if (entity.damage(entity.getWorld().getDamageSources().trident(owner == null ? this : owner, owner == null ? this : owner), damage)) {
			if (entity.getType() == EntityType.ENDERMAN) {
				return;
			}
			if (entity instanceof LivingEntity livingEntity) {
				if (owner instanceof LivingEntity livingOwner) {
					EnchantmentHelper.onUserDamaged(livingEntity, owner);
					EnchantmentHelper.onTargetDamaged(livingOwner, livingEntity);
				}
				onHit(livingEntity);
			}
		}
		setVelocity(getVelocity().multiply(-0.01, -0.1, -0.01));
	}

@Nullable
	@Override
	protected EntityHitResult getEntityCollision(Vec3d currentPosition, Vec3d nextPosition) {
		if (isOwnerAlive()) {
			EntityHitResult collision = ProjectileUtil.getEntityCollision(getWorld(), this, currentPosition, nextPosition, getBoundingBox().stretch(getVelocity()).expand(1), this::canHit);
			if (collision != null && collision.getEntity() instanceof MobEntity mob && getOwner().getUuid().equals(BWComponents.MINION_COMPONENT.get(mob).getMaster())) {
				return null;
			}
		}
		return dealtDamage ? null : super.getEntityCollision(currentPosition, nextPosition);
	}

@Override
	public void onPlayerCollision(PlayerEntity player) {
		Entity owner = getOwner();
		if (owner == null || owner.getUuid() == player.getUuid()) {
			super.onPlayerCollision(player);
		}
	}

@Override
	public void tick() {
		if (inGroundTime > 4) {
			dealtDamage = true;
		}
		Entity entity = getOwner();
		if (entity instanceof PlayerEntity && (dealtDamage || isNoClip() || getY() <= getWorld().getBottomY())) {
			if (!isOwnerAlive()) {
				if (!getWorld().isClient && pickupType == PersistentProjectileEntity.PickupPermission.ALLOWED) {
					dropStack(asItemStack(), 0.1f);
				}
				remove(RemovalReason.DISCARDED);
			} else {
				setNoClip(true);
				Vec3d vec3d = new Vec3d(entity.getX() - getX(), entity.getEyeY() - getY(), entity.getZ() - getZ());
				setPos(getX(), getY() + vec3d.y * 0.1, getZ());
				if (getWorld().isClient) {
					lastRenderY = getY();
				}
				setVelocity(getVelocity().multiply(0.95d).add(vec3d.normalize().multiply(0.3)));
			}
		}
		super.tick();
	}

@Override
	protected void age() {
		if (pickupType != PickupPermission.ALLOWED) {
			super.age();
		}
	}

@Override
	public void readCustomDataFromNbt(NbtCompound nbt) {
		super.readCustomDataFromNbt(nbt);
		spear = ItemStack.fromNbt(nbt.getCompound("Spear"));
		dealtDamage = nbt.getBoolean("DealtDamage");
	}

@Override
	public void writeCustomDataToNbt(NbtCompound nbt) {
		super.writeCustomDataToNbt(nbt);
		nbt.put("Spear", spear.writeNbt(new NbtCompound()));
		nbt.putBoolean("DealtDamage", dealtDamage);
	}

private boolean isOwnerAlive() {
		Entity entity = getOwner();
		if (entity != null && entity.isAlive()) {
			return !(entity instanceof ServerPlayerEntity) || !entity.isSpectator();
		} else {
			return false;
		}
	}

public static void send(ServerPlayerEntity player, HornedSpearEntity entity) {
		PacketByteBuf buf = new PacketByteBuf(Unpooled.buffer());
		buf.writeInt(entity.getId());
		buf.writeItemStack(entity.spear);
		ServerPlayNetworking.send(player, ID, buf);
	}

@Override
		public void receive(MinecraftClient client, ClientPlayNetworkHandler handler, PacketByteBuf buf, PacketSender responseSender) {
			int entityId = buf.readInt();
			ItemStack spear = buf.readItemStack();
			client.execute(() -> ((HornedSpearEntity) client.world.getEntityById(entityId)).spear = spear);
		}

@Override
	public void receiveMessage(IPayloadContext context) {
		context.enqueueWork(() -> AoAPlayerEventListener.onKeyPress(context.player(), this.abilities));
	}

public void handleKeyInput(InputConstants.Key key) {
		if (ClientOperations.getPlayer() == null || this.keyListeners.isEmpty())
			return;

		List<String> abilities = null;

		for (KeyMapping keyMap : KeyMapping.MAP.getAll(key)) {
			for (AoAPlayerKeybindListener listener : this.keyListeners.getOrDefault(keyMap, List.of())) {
				if (listener.isListenerActive() && listener.getEventListener() instanceof AoAAbility.Instance abilityInstance && listener.shouldSendKeyPress()) {
					if (abilities == null)
						abilities = new ObjectArrayList<>(1);

					abilities.add(abilityInstance.getUniqueIdentifier());
				}
			}
		}

		if (abilities != null && !abilities.isEmpty())
			AoANetworking.sendToServer(new PlayerAbilityKeybindTriggerPacket(abilities));
	}

@ApiStatus.Internal
	static void onKeyPress(final Player player, final List<String> abilityListeners) {
		PlayerDataManager plData = PlayerUtil.getAdventPlayer(player);

		for (String str : abilityListeners) {
			AoAAbility.Instance ability = plData.getAbility(str);

			if (ability != null)
				ability.handleKeyInput();
		}
	}

@Override
	public void handleKeyInput() {
		if (getPlayer() instanceof ServerPlayer player) {
			if (!primedAttack && skill.getPlayerDataManager().getResource(AoAResources.ENERGY.get()).hasAmount(this.energyCost)) {
				this.primedAttack = true;

				activatedActionKey(player);
			}
		}
	}

private void handleAfterAttacking(LivingDamageEvent.Post ev) {
		if (ev.getNewDamage() > 0 && primedAttack && DamageUtil.isMeleeDamage(ev.getSource()) && !getPlayer().getItemInHand(InteractionHand.OFF_HAND).isEmpty()) {
			this.primedAttack = false;

			if (skill.getPlayerDataManager().getResource(AoAResources.ENERGY.get()).consume(this.energyCost, true)) {
				ServerPlayer player = (ServerPlayer)getPlayer();
				LivingEntity target = ev.getEntity();

				AoAScheduler.schedule(player.getCurrentSwingDuration() - 1, tick -> {
					player.swing(InteractionHand.OFF_HAND, true);

					if (target != null && target.isAlive()) {
						if (player.distanceToSqr(target) < 36 && player.hasLineOfSight(target)) {
							DamageUtil.doScaledKnockback(target, player, 0.3f, 1, 1, 1);
							EntityUtil.applyPotions(target, player, new EffectBuilder(MobEffects.MOVEMENT_SLOWDOWN, this.stunDuration).level(127), new EffectBuilder(MobEffects.DIG_SLOWDOWN, this.stunDuration).level(127));
							activatedActionKey(player);

							if (skill.canGainXp(true))
								PlayerUtil.giveTimeBasedXpToPlayer(player, this.skill.type(), 39,  false);
						}
					}
				});
			}
		}
	}

@Override
	public void handleKeyInput() {
		if (getPlayer() instanceof ServerPlayer player) {
			if (this.skill.getPlayerDataManager().getResource(AoAResources.ENERGY.get()).consume(this.energyCost, true)) {
				activatedActionKey(player);

				if (this.skill.canGainXp(true))
					PlayerUtil.giveTimeBasedXpToPlayer(player, this.skill.type(), 20,  false);
			}
		}
	}

private void handleIncomingDamage(LivingIncomingDamageEvent ev) {
		if (ev.getEntity().level().getGameTime() < this.activationTime + 5 && DamageUtil.isMeleeDamage(ev.getSource()))
			ev.setCanceled(true);
	}
